<span class="line">      <span class="token keyword">const</span> userInfo <span class="token operator">=</span> userStore<span class="token punctuation">.</span>userInfo <span class="token operator">||</span> <span class="token punctuation">(</span><span class="token keyword">await</span> authStore<span class="token punctuation">.</span><span class="token function">fetchUserInfo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
